-- 3. DATA DIAGNOSTICS - Understanding the Data Distribution
-- ============================================================================

\echo ''
\echo '======================================================================='
\echo 'DIAGNOSTIC: Rows matching edge_id range only'
\echo '======================================================================='
SELECT COUNT(*) as rows_in_edge_range
FROM edge_quadkey_association 
WHERE edge_id >= 122563426 AND edge_id < 123688919;

\echo ''
\echo '======================================================================='
\echo 'DIAGNOSTIC: Rows matching quadkeys only (sample of 10)'
\echo '======================================================================='
SELECT COUNT(*) as rows_matching_quadkeys
FROM edge_quadkey_association 
WHERE quadkey IN (
    '122112223301031', '122112223321320', '122112223302123', '122112223303113',
    '122112223300033', '122112223132023', '122112223303033', '122112223301312',
    '122112223302001', '122112223123230'  -- Only first 10 for quick check
);

\echo ''
\echo '======================================================================='
\echo 'DIAGNOSTIC: Rows matching BOTH conditions'
\echo '======================================================================='
SELECT COUNT(*) as rows_matching_both
FROM edge_quadkey_association 
WHERE quadkey = ANY(ARRAY[
    '122112223301031', '122112223321320', '122112223302123', '122112223303113',
    '122112223300033', '122112223132023', '122112223303033', '122112223301312',
    '122112223302001', '122112223123230'  -- Only first 10 for quick check
]::varchar[])
AND edge_id >= 122563426 AND edge_id < 123688919;

\echo ''
\echo '======================================================================='
\echo 'KEY INSIGHT:'
\echo 'If rows_in_edge_range >> rows_matching_both, then PK approach is better'
\echo 'Because: 436 PK lookups < scanning thousands of edge_id rows'
\echo '======================================================================='
